beforeExample:
package test;

import org.eclipse.jdt.core.IClasspathAttribute;
import org.eclipse.jdt.core.JavaCore;

public class TestClass {
    public IClasspathAttribute[] addModuleAttributeIfNeeded(IClasspathAttribute[] extraAttributes) {
        for (int j = 0; j < extraAttributes.length; j++) {
            IClasspathAttribute classpathAttribute = extraAttributes[j];
            if (IClasspathAttribute.AUTOMATIC_MODULE.equals(classpathAttribute.getName())) {
                extraAttributes[j] = JavaCore.newClasspathAttribute(IClasspathAttribute.AUTOMATIC_MODULE, "true");
                return extraAttributes;
            }
        }
        return new IClasspathAttribute[0];
    }

    public static final String FIELD_MODULE_NAME = IClasspathAttribute.AUTOMATIC_MODULE;

    public boolean checkAttributeKey(String key) {
        return key.equals(IClasspathAttribute.AUTOMATIC_MODULE);
    }
}

